#!/usr/bin/env bash
#
# Pull the latest code and put it live.
#
# `git pull` on its own is NOT enough, for two reasons that are easy to miss:
#
#   1. Asterisk reads /etc/asterisk, not this repo. A new dialplan context or
#      a new amd.conf sits in the working tree doing nothing until it is
#      copied across and reloaded.
#   2. Node has the old code in memory until the service restarts.
#
# And one thing this script deliberately does NOT do: copy pjsip.conf.
# That file is GENERATED by the UI from your saved trunks. The copy in this
# repo is an empty placeholder, so copying it over would delete every trunk
# you have configured. Trunk changes go live when you press Save on the
# Trunks tab, which rewrites it and reloads PJSIP.
#
set -euo pipefail

cd "$(dirname "$0")/.."
REPO="$(pwd)"
SERVICE="shadowpbx-campaign"
ETC="/etc/asterisk"

say() { printf '\n\033[1;36m==> %s\033[0m\n' "$*"; }
warn() { printf '\033[1;33m    ! %s\033[0m\n' "$*"; }

[ "$(id -u)" -eq 0 ] || { echo "Run this as root."; exit 1; }

say "Pulling the latest code"
BEFORE="$(git rev-parse HEAD)"
git pull --ff-only
AFTER="$(git rev-parse HEAD)"
if [ "$BEFORE" = "$AFTER" ]; then
  echo "    already up to date ($(git log --oneline -1))"
else
  git --no-pager log --oneline "$BEFORE..$AFTER" | sed 's/^/    /'
fi

if ! git diff --quiet "$BEFORE" "$AFTER" -- package.json package-lock.json 2>/dev/null; then
  say "Dependencies changed — installing"
  npm install --omit=dev
fi

say "Updating Asterisk config"
# Same substitution the installer uses, so a config referencing ${ARI_PASS}
# lands with the real value rather than the literal text.
set -a; [ -f .env ] && . ./.env; set +a
VARS='${TRUNK_HOST} ${TRUNK_USER} ${TRUNK_PASS} ${PBX_HOST} ${PBX_PORT} ${ARI_PASS}'
CHANGED=0
DIALPLAN=0
for f in extensions.conf ari.conf http.conf rtp.conf amd.conf; do
  [ -f "asterisk/$f" ] || continue
  TMP="$(mktemp)"
  envsubst "$VARS" < "asterisk/$f" > "$TMP"
  if [ -f "$ETC/$f" ] && cmp -s "$TMP" "$ETC/$f"; then
    rm -f "$TMP"; continue
  fi
  [ -f "$ETC/$f" ] && cp "$ETC/$f" "$ETC/$f.bak-$(date +%F-%H%M%S)"
  mv "$TMP" "$ETC/$f"; chmod 640 "$ETC/$f"
  echo "    updated $f"
  CHANGED=1
  [ "$f" = "extensions.conf" ] && DIALPLAN=1
done
[ "$CHANGED" -eq 0 ] && echo "    no changes"
echo "    (pjsip.conf left alone — the UI owns it; press Save on a trunk to rewrite it)"

if [ "$CHANGED" -eq 1 ]; then
  say "Reloading Asterisk"
  [ "$DIALPLAN" -eq 1 ] && asterisk -rx "dialplan reload" | sed 's/^/    /'
  # Reloading a module that was never loaded is not an error worth stopping
  # for -- AMD is optional and the app falls back to treating every call as
  # human when it is missing.
  asterisk -rx "module reload app_amd.so" >/dev/null 2>&1 \
    || warn "app_amd.so not loaded — answering-machine detection will pass every call through as human"
fi

say "Restarting $SERVICE"
systemctl restart "$SERVICE"
sleep 2
if systemctl is-active --quiet "$SERVICE"; then
  echo "    running — $(git log --oneline -1)"
else
  warn "service did not come back up:"
  journalctl -u "$SERVICE" -n 20 --no-pager | sed 's/^/    /'
  exit 1
fi

say "Done"
echo "    Settings stored in data/ and config/ are untouched."
echo "    Anything set in the UI (trunks, flows, campaigns) is unchanged."
